import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.CchDE9cb.js";const g=JSON.parse('{"title":"Upgrades","description":"How to upgrade a self-hosted CapacityLens instance safely, what happens to the database on a schema change, and how to roll back.","frontmatter":{"title":"Upgrades","description":"How to upgrade a self-hosted CapacityLens instance safely, what happens to the database on a schema change, and how to roll back."},"headers":[],"relativePath":"self-hosting/upgrades.md","filePath":"self-hosting/upgrades.md","lastUpdated":null}'),n={name:"self-hosting/upgrades.md"};function r(o,e,h,l,p,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="upgrades" tabindex="-1">Upgrades <a class="header-anchor" href="#upgrades" aria-label="Permalink to &quot;Upgrades&quot;">​</a></h1><p>CapacityLens upgrades in place: pull the new release, rebuild, and restart. Schema changes are handled automatically and safely, with an automatic rollback snapshot taken before anything changes. This page is the upgrade procedure and its rollback path.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Always take a fresh backup immediately before upgrading, even though the server also takes its own pre-migration snapshot automatically. See <a href="/capacitylens/self-hosting/backups-and-restore">Backups and restore</a>.</p></div><h2 id="one-time-check-for-older-compose-installations" tabindex="-1">One-time check for older Compose installations <a class="header-anchor" href="#one-time-check-for-older-compose-installations" aria-label="Permalink to &quot;One-time check for older Compose installations&quot;">​</a></h2><p>If your installation was created before the Compose project name was pinned to <code>capacitylens</code>, do this once, before your next upgrade. Identify the database volume attached to the currently running API:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db_volume</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose ps </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api)&quot; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{{range .Mounts}}{{if eq .Destination &quot;/data&quot;}}{{.Name}}{{end}}{{end}}&#39;)&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Database volume: %s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$db_volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>If that name isn&#39;t <code>capacitylens_capacitylens-db</code>, take the prefix before <code>_capacitylens-db</code> and add it to your existing <code>.env</code>, for example <code>COMPOSE_PROJECT_NAME=floaty-v1</code>. Keep that override for the life of the install. After pulling the new release, run <code>docker compose config</code> and confirm its three rendered physical volume names carry the same historical prefix before starting anything. If more than one candidate prefix exists, stop and identify the volume mounted by the old API rather than guessing.</p><h2 id="upgrade-procedure" tabindex="-1">Upgrade procedure <a class="header-anchor" href="#upgrade-procedure" aria-label="Permalink to &quot;Upgrade procedure&quot;">​</a></h2><ol><li><p>Take a fresh, explicit snapshot and keep it outside the release tree. A recent restore test proves the <em>procedure</em> works — it isn&#39;t a current copy of live data, so keep an off-host copy too. See <a href="/capacitylens/self-hosting/backups-and-restore">Backups and restore</a>.</p></li><li><p>Confirm you have a recent, successful restore test on record.</p></li><li><p>Read <code>CHANGELOG.md</code> for migrations or breaking changes in the target release.</p></li><li><p>Pull the target tag and rebuild all three targets. For Compose:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Compose recreates each service in place, one at a time: the old <code>api</code> container is stopped before the new one starts, and <code>web</code> waits for the new <code>api</code> to report healthy before it&#39;s recreated in turn — so there&#39;s no window where two API versions hold the SQLite file open together. Expect a brief gap, seconds not minutes, where requests are refused or retried while the old process exits and the new one comes up; that&#39;s normal restart behavior, not data loss. Mixed-version writers — old and new API against the same database at once — are not supported, and if anything outside this procedure ever created that overlap, the migration ledger&#39;s per-step checksums and transactional writes are what stand between you and a corrupted schema, not this command. This step also reruns the internal certificate initializer and reloads the resulting identity into both long-running services.</p></li><li><p>On first start, if the database needs a schema upgrade, CapacityLens automatically creates and verifies a <code>capacitylens-pre-migration-vN-to-vM.db</code> snapshot before making any schema change. If that snapshot creation fails, startup refuses rather than proceeding — resolve the underlying storage or permissions problem rather than bypassing the snapshot.</p></li><li><p>Check API health, sign in, confirm account access, and make one safe write.</p></li><li><p>Keep the old container image and the recovery snapshot until you&#39;re satisfied the upgrade is good.</p></li></ol><h2 id="roll-back" tabindex="-1">Roll back <a class="header-anchor" href="#roll-back" aria-label="Permalink to &quot;Roll back&quot;">​</a></h2><p>Rollback means stopping the API, restoring the pre-migration snapshot this release created (or, if there wasn&#39;t one, the explicit snapshot from step 1) with no stale <code>-wal</code>/<code>-shm</code> files, then starting the old image again. An old image deliberately refuses to start against an upgraded database — CapacityLens has no down migrations, so rollback always means restoring the matching snapshot, not just switching images back.</p><p>For Docker Compose&#39;s named volumes, use the <a href="/capacitylens/self-hosting/backups-and-restore#docker-compose-named-volume-procedure">restore procedure in Backups and restore</a> with the exact <code>capacitylens-pre-migration-vN-to-vM.db</code> filename, rather than copying host paths — the database lives in a named volume, not on the host filesystem.</p><h2 id="release-directory-deployments" tabindex="-1">Release-directory deployments <a class="header-anchor" href="#release-directory-deployments" aria-label="Permalink to &quot;Release-directory deployments&quot;">​</a></h2><p>If your platform builds into versioned release directories and switches a stable <code>current</code> symlink (Capistrano-style deploys, for example), coordinate that switch with the running API process: build the new release while the existing process keeps serving traffic, stop the process immediately before activating the new release and cleaning up the old one, then restart it from the stable path and verify <code>/api/health</code>.</p><p>Don&#39;t purge a release directory while a running service still has it as its working directory. Keep the database, backups, environment file and operational logs outside the release tree, so activation and rollback never replace persistent state.</p><h2 id="before-a-schema-bearing-release-maintainers" tabindex="-1">Before a schema-bearing release (maintainers) <a class="header-anchor" href="#before-a-schema-bearing-release-maintainers" aria-label="Permalink to &quot;Before a schema-bearing release (maintainers)&quot;">​</a></h2><p>Before shipping a release that changes the schema, run the migration rehearsal against the committed auth fixture and again against a representative database:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rehearse:migrations</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rehearse:migrations</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/representative.db</span></span></code></pre></div><p>The source database is copied with SQLite&#39;s online backup API and is never itself migrated; the temporary copy is anonymised, vacuumed, and deleted unless <code>--keep</code> is passed. A passing rehearsal proves the happy path, the verified rollback snapshot, the migration-ledger checksum, an injected disk-exhaustion rollback, recovery from a forced process termination at the final pending migration, completion of the remaining chain after reopening, and an idempotent reopen for that database shape. It never prints tenant content — record the source schema version and row/table counts it prints, along with the result, in your release evidence.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/capacitylens/self-hosting/backups-and-restore">Backups and restore</a> for the restore drill this page&#39;s rollback path relies on.</li><li><a href="/capacitylens/self-hosting/monitoring">Monitoring and health checks</a> to confirm the upgraded instance is healthy.</li></ul>`,21)])])}const k=a(n,[["render",r]]);export{g as __pageData,k as default};
